#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <string>
using namespace std;

int main(){
double heavy=4,nesterov=4,vHeavy=0,vNesterov=0;
double lr=0.08,momentum=0.8;
for(int i=0;i<30;i++){
    double gradHeavy=2*(heavy-1);
    vHeavy=momentum*vHeavy-lr*gradHeavy;
    heavy+=vHeavy;
    double lookahead=nesterov+momentum*vNesterov;
    double gradNesterov=2*(lookahead-1);
    vNesterov=momentum*vNesterov-lr*gradNesterov;
    nesterov+=vNesterov;
}
cout<<"Heavy-ball "<<heavy<<" Nesterov "<<nesterov<<endl;
    return 0;
}

