#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <string>
using namespace std;

int main(){
vector<double> before={1,2,1,2},after={3,4,3,4};
auto measure=[](const vector<double>& data){
    double mean=0,variance=0;
    for(double value:data)mean+=value/data.size();
    for(double value:data)variance+=pow(value-mean,2)/data.size();
    return vector<double>{mean,variance};
};
vector<double> a=measure(before),b=measure(after);
cout<<"Mean difference "<<b[0]-a[0]
    <<" variance difference "<<b[1]-a[1]<<endl;
    return 0;
}

