#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <string>
using namespace std;

int main(){
vector<double> treeA={1,2,3,4},treeB={1.1,2.2,2.9,3.8};
double ma=0,mb=0,va=0,vb=0,cov=0;
for(int i=0;i<int(treeA.size());i++){
    ma+=treeA[i]/treeA.size();mb+=treeB[i]/treeB.size();
}
for(int i=0;i<int(treeA.size());i++){
    double a=treeA[i]-ma,b=treeB[i]-mb;
    va+=a*a/treeA.size();vb+=b*b/treeB.size();cov+=a*b/treeA.size();
}
cout<<"Ensemble variance "<<(va+vb+2*cov)/4<<endl;
    return 0;
}

