#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <string>
using namespace std;

int main(){
vector<double> observation={1,2};
double w[2]={1,-0.4},bias=-0.5;
auto score=[&](const vector<double>& x){return w[0]*x[0]+w[1]*x[1]+bias;};
double original=score(observation);
for(double candidate:{0.5,1.5,2.5}){
    vector<double> counterfactual=observation;
    counterfactual[0]=candidate;
    cout<<candidate<<" "<<score(counterfactual)
        <<" changed class "<<((score(counterfactual)>=0)!=(original>=0))<<endl;
}
    return 0;
}

