#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <string>
using namespace std;

int main(){
vector<double> values={1,2,3,4,5};
int window=2;
for(int t=0;t<int(values.size());t++){
    int begin=max(0,t-window+1);
    double sum=0,weighted=0;
    for(int j=begin;j<=t;j++){
        double weight=exp((values[j]-values[t])*0.1);
        sum+=weight;weighted+=weight*values[j];
    }
    cout<<t<<" local attention "<<weighted/sum<<endl;
}
    return 0;
}
